+--
+--  SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
+--
+
+pragma Assertion_Policy (Ghost          => Ignore,
+                         Pre            => Ignore,
+                         Post           => Ignore,
+                         Assert         => Ignore,
+                         Loop_Invariant => Ignore);
+
+package body Heaps.Radix with SPARK_Mode is
+
+   package KM renames Key_Multisets;
+
+   function Bucket_Of (K, Base : Key_Type) return Bucket_Index is
+      Distance : Key_Type := K - Base;
+      Limit    : Key_Type := Key_Type'Last;
+      Result   : Bucket_Index := 0;
+   begin
+      while Distance > 0 loop
+         pragma Loop_Invariant (Distance >= 0);
+         pragma Loop_Invariant (Distance <= Limit);
+         pragma Loop_Invariant (Limit >= 0);
+         pragma Loop_Invariant
+           (Result < Bucket_Index'Last or else Limit = 0);
+         pragma Loop_Variant (Decreases => Distance);
+
+         pragma Assert (Result < Bucket_Index'Last);
+         Distance := Distance / 2;
+         Limit := Limit / 2;
+         Result := Result + 1;
+      end loop;
+      return Result;
+   end Bucket_Of;
+
+   procedure Lemma_Total_Same (A, B : Heap; At_Bucket : Bucket_Index)
+     with Ghost,
+          Pre  => (for all P in At_Bucket .. Bucket_Index'Last =>
+                    A.Counts (P) = B.Counts (P)),
+          Post => Total_From (A, At_Bucket) = Total_From (B, At_Bucket),
+          Subprogram_Variant => (Increases => At_Bucket);
+
+   procedure Lemma_Total_Increment
+     (Old_H, New_H : Heap; Changed, At_Bucket : Bucket_Index)
+     with Ghost,
+          Pre  => At_Bucket <= Changed
+                  and then Old_H.Counts (Changed) < Max_Capacity
+                  and then New_H.Counts (Changed)
+                             = Old_H.Counts (Changed) + 1
+                  and then
+                    (for all P in Bucket_Index =>
+                       (if P /= Changed
+                        then New_H.Counts (P) = Old_H.Counts (P))),
+          Post => Total_From (New_H, At_Bucket)
+                    = Total_From (Old_H, At_Bucket) + 1,
+          Subprogram_Variant => (Increases => At_Bucket);
+
+   procedure Lemma_Count_Bounded
+     (H : Heap; B, At_Bucket : Bucket_Index)
+     with Ghost,
+          Pre  => Is_Heap (H) and then At_Bucket <= B,
+          Post => SPARK.Big_Integers.To_Big_Integer (H.Counts (B))
+                    <= Total_From (H, At_Bucket),
+          Subprogram_Variant => (Increases => At_Bucket);
+
+   procedure Lemma_Total_Zero (H : Heap; At_Bucket : Bucket_Index)
+     with Ghost,
+          Pre  => (for all P in At_Bucket .. Bucket_Index'Last =>
+                    H.Counts (P) = 0),
+          Post => Total_From (H, At_Bucket) = 0,
+          Subprogram_Variant => (Increases => At_Bucket);
+
+   procedure Lemma_Total_Same (A, B : Heap; At_Bucket : Bucket_Index) is
+   begin
+      if At_Bucket < Bucket_Index'Last then
+         Lemma_Total_Same (A, B, Bucket_Index'Succ (At_Bucket));
+      end if;
+   end Lemma_Total_Same;
+
+   procedure Lemma_Total_Increment
+     (Old_H, New_H : Heap; Changed, At_Bucket : Bucket_Index)
+   is
+   begin
+      if At_Bucket < Changed then
+         Lemma_Total_Increment
+           (Old_H, New_H, Changed, Bucket_Index'Succ (At_Bucket));
+      elsif At_Bucket < Bucket_Index'Last then
+         Lemma_Total_Same
+           (Old_H, New_H, Bucket_Index'Succ (At_Bucket));
+      end if;
+   end Lemma_Total_Increment;
+
+   procedure Lemma_Count_Bounded
+     (H : Heap; B, At_Bucket : Bucket_Index) is
+   begin
+      if At_Bucket < B then
+         Lemma_Count_Bounded
+           (H, B, Bucket_Index'Succ (At_Bucket));
+      end if;
+   end Lemma_Count_Bounded;
+
+   procedure Lemma_Total_Zero (H : Heap; At_Bucket : Bucket_Index) is
+   begin
+      if At_Bucket < Bucket_Index'Last then
+         Lemma_Total_Zero (H, Bucket_Index'Succ (At_Bucket));
+      end if;
+   end Lemma_Total_Zero;
+
+   procedure Clear (H : in out Heap) is
+   begin
+      for B in Bucket_Index loop
+         H.Heads (B) := 0;
+         H.Counts (B) := 0;
+
+         pragma Loop_Invariant
+           (for all P in Bucket_Index'First .. B =>
+              H.Heads (P) = 0 and then H.Counts (P) = 0);
+      end loop;
+
+      H.Last := 0;
+      H.Base := 0;
+      Lemma_Total_Zero (H, Bucket_Index'First);
+   end Clear;
+
+   function Peek_Min (H : Heap) return Key_Type is
+      Result : Key_Type := H.Keys (1);
+   begin
+      for I in 2 .. H.Last loop
+         if H.Keys (I) < Result then
+            Result := H.Keys (I);
+         end if;
+
+         pragma Loop_Invariant (for all J in 1 .. I => Result <= H.Keys (J));
+         pragma Loop_Invariant (for some J in 1 .. I => Result = H.Keys (J));
+      end loop;
+      return Result;
+   end Peek_Min;
+
+   procedure Insert (H : in out Heap; K : Key_Type) is
+      Before    : constant Key_Array := H.Keys with Ghost;
+      Old_H     : constant Heap := H with Ghost;
+      Slot      : constant Index := H.Last + 1;
+      B         : constant Bucket_Index := Bucket_Of (K, H.Base);
+      Old_Head  : constant Extended_Index := H.Heads (B);
+      Old_Count : constant Extended_Index := H.Counts (B);
+   begin
+      Lemma_Count_Bounded (H, B, Bucket_Index'First);
+      pragma Assert (Old_Count <= H.Last);
+      pragma Assert (Old_Count < H.Capacity);
+
+      H.Last := Slot;
+      H.Keys (Slot) := K;
+      H.Links (Slot) :=
+        (Prev   => 0,
+         Next   => Old_Head,
+         Length => Old_Count + 1);
+
+      if Old_Head /= 0 then
+         H.Links (Old_Head).Prev := Slot;
+      end if;
+
+      H.Heads (B) := Slot;
+      H.Counts (B) := Old_Count + 1;
+
+      Lemma_Total_Increment (Old_H, H, B, Bucket_Index'First);
+
+      pragma Assert (Node_Valid (H, Slot));
+      pragma Assert
+        (for all I in 1 .. Old_H.Last =>
+           (if I = Old_Head then Node_Valid (H, I)
+            else Node_Valid (H, I)));
+      pragma Assert
+        (for all P in Bucket_Index => Bucket_Valid (H, P));
+      pragma Assert (Is_Heap (H));
+
+      Models.Lemma_Same_Prefix (Before, H.Keys, H.Last - 1);
+      Models.Lemma_Add_Congruent
+        (Models.Occurrences (Before, H.Last - 1),
+         Models.Occurrences (H.Keys, H.Last - 1), K);
+   end Insert;
+
+   procedure Meld (Into : in out Heap; From : in out Heap) is
+      M0   : constant KM.Multiset := Model (Into) with Ghost;
+      Base : constant Extended_Index := Into.Last;
+   begin
+      for I in 1 .. From.Last loop
+         pragma Assert (Node_Valid (From, I));
+         pragma Assert (From.Keys (I) >= From.Base);
+         pragma Assert (From.Keys (I) >= Into.Base);
+         Insert (Into, From.Keys (I));
+         Models.Lemma_Sum_Add
+           (M0, Models.Occurrences (From.Keys, I - 1), From.Keys (I));
+         Models.Lemma_Sum_Empty (M0);
+
+         pragma Loop_Invariant (Is_Heap (Into));
+         pragma Loop_Invariant (Into.Last = Base + I);
+         pragma Loop_Invariant (Into.Base = Into.Base'Loop_Entry);
+         pragma Loop_Invariant
+           (Model (Into) = M0 + Models.Occurrences (From.Keys, I));
+      end loop;
+
+      if From.Last = 0 then
+         Models.Lemma_Sum_Empty (M0);
+      end if;
+
+      Clear (From);
+   end Meld;
+
+   procedure Extract_Min (H : in out Heap; K : out Key_Type) is
+      Before          : constant Key_Array := H.Keys with Ghost;
+      Old_Base        : constant Key_Type := H.Base;
+      Old_Last        : constant Index := H.Last;
+      Min_At          : Index := 1;
+      Target_Last     : Extended_Index;
+      Remaining_Model : KM.Multiset with Ghost;
+   begin
+      --  The smallest key is found before Base moves. This scan is also the
+      --  proof that every key redistributed below satisfies the monotone
+      --  insertion precondition with the new Base.
+
+      for I in 2 .. H.Last loop
+         if H.Keys (I) < H.Keys (Min_At) then
+            Min_At := I;
+         end if;
+
+         pragma Loop_Invariant (Min_At <= I);
+         pragma Loop_Invariant
+           (for all J in 1 .. I => H.Keys (Min_At) <= H.Keys (J));
+      end loop;
+
+      K := H.Keys (Min_At);
+      pragma Assert (K >= Old_Base);
+
+      --  Remove one occurrence from the dense model. Bucket links are rebuilt
+      --  afterwards, so the physical last key can simply fill the hole.
+
+      H.Keys (Min_At) := H.Keys (Old_Last);
+
+      if Min_At < Old_Last then
+         Models.Lemma_Set (Before, H.Keys, Min_At, Old_Last - 1);
+      else
+         Models.Lemma_Same_Prefix (Before, H.Keys, Old_Last - 1);
+         Models.Lemma_Add_Congruent
+           (Models.Occurrences (H.Keys, Old_Last - 1),
+            Models.Occurrences (Before, Old_Last - 1), K);
+      end if;
+
+      Target_Last := Old_Last - 1;
+      Remaining_Model := Models.Occurrences (H.Keys, Target_Last);
+      pragma Assert (Model (H) = KM.Add (Remaining_Model, K));
+      pragma Assert
+        (for all I in 1 .. Target_Last => K <= H.Keys (I));
+
+      --  Advancing Base changes every bucket definition. Rebuilding all
+      --  chains through Insert keeps the executable representation simple
+      --  and gives the rebuild exactly the same invariant as normal filling.
+
+      H.Last := 0;
+      H.Base := K;
+      for B in Bucket_Index loop
+         H.Heads (B) := 0;
+         H.Counts (B) := 0;
+
+         pragma Loop_Invariant
+           (for all P in Bucket_Index'First .. B =>
+              H.Heads (P) = 0 and then H.Counts (P) = 0);
+      end loop;
+      Lemma_Total_Zero (H, Bucket_Index'First);
+      pragma Assert (Is_Heap (H));
+
+      for I in 1 .. Target_Last loop
+         declare
+            V : constant Key_Type := H.Keys (I);
+         begin
+            pragma Assert (V >= H.Base);
+            Insert (H, V);
+         end;
+
+         pragma Loop_Invariant (H.Last = I);
+         pragma Loop_Invariant (H.Base = K);
+         pragma Loop_Invariant (Is_Heap (H));
+         pragma Loop_Invariant
+           (for all J in 1 .. Target_Last => K <= H.Keys (J));
+      end loop;
+
+      Models.Lemma_Same_Prefix (H.Keys, H.Keys, Target_Last);
+      pragma Assert (Model (H) = Remaining_Model);
+      Models.Lemma_Add_Congruent (Model (H), Remaining_Model, K);
+   end Extract_Min;
+
+end Heaps.Radix;

